    public static class NativeQualityTests {
        static int passed;static readonly List<string> Failures=new List<string>();const long Epoch=1767225600;
        static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        static void Case(string name,Action action){try{action();passed++;}catch(Exception error){Failures.Add(name+": "+error.GetBaseException().Message);}}
        static void Reject(Action action,string fragment){try{action();}catch(Exception error){if(error.Message.IndexOf(fragment,StringComparison.OrdinalIgnoreCase)>=0)return;throw;}throw new InvalidOperationException("Expected rejection: "+fragment);}
        static long I(Dictionary<string,object> row,string key){return Convert.ToInt64(row[key]);}
