            Case("WPR events and coverage",delegate{var row=DiagnosticQuality.Wpr(WprText(),Epoch+5,Epoch+65);Check(I(row,"gpu_kernel_events")==25&&I(row,"cpu_samples")==10,"WPR counts changed.");});
