            Case("WPR loss and short recording",delegate{Reject(()=>DiagnosticQuality.Wpr(WprText().Replace("Lost Events : 0","Lost Events : 1"),Epoch,Epoch+60),"lost events");Reject(()=>DiagnosticQuality.Wpr(WprText(),Epoch,Epoch+80),"does not cover");});
