            using(var fixture=new NativeTestFixture(root,"quality")){
                Case("native detach completion",delegate{var receipt=M("sequence",42,"action","vtune-detach","accepted",true,"error",null,"applied_unix_ns",1767225601000000000L);fixture.Json("vtune-control.json",receipt);var state=M("vtune_detach_sequence",42,"vtune_stop_method","native-itt-detach","vtune_exit_code",-1,"vtune_detached_utc","2026-01-01T00:00:01Z");Reject(()=>DiagnosticQuality.VtuneControl(fixture.Root,state),"completion evidence");state["vtune_exit_code"]=0;Check(I(DiagnosticQuality.VtuneControl(fixture.Root,state),"native_receipt_sequence")==42,"Valid detach rejected.");receipt["sequence"]=41;fixture.Json("vtune-control.json",receipt);Reject(()=>DiagnosticQuality.VtuneControl(fixture.Root,state),"completion evidence");});
                Case("orderly export and exit",delegate{var state=M("nsight_exit_code",0,"vtune_exit_code",0,"window_finished","2026-01-01T00:01:00Z");var ready=M("pid",42,"policy","engine-shutdown-self-terminate","nsight_exit_code",0,"vtune_completed",true);var receipt=M("pid",42,"policy",ready["policy"],"shutdown_completed",true,"exit_code",0,"exit_unix_ns",1767225661000000000L);fixture.Json("exit-ready.json",ready);fixture.Json("exit-completed.json",receipt);Check((bool)DiagnosticQuality.Exit(fixture.Root,state,42)["engine_shutdown_completed"],"Valid shutdown rejected.");state["nsight_exit_code"]=-1;Reject(()=>DiagnosticQuality.Exit(fixture.Root,state,42),"completion or engine shutdown");state["nsight_exit_code"]=0;receipt["shutdown_completed"]=false;fixture.Json("exit-completed.json",receipt);Reject(()=>DiagnosticQuality.Exit(fixture.Root,state,42),"completion or engine shutdown");receipt["shutdown_completed"]=true;receipt["pid"]=41;fixture.Json("exit-completed.json",receipt);Reject(()=>DiagnosticQuality.Exit(fixture.Root,state,42),"completion or engine shutdown");});
                Case("WPR gameplay PID filtering",delegate{var state=M("window_started","2026-01-01T00:00:05Z","window_finished","2026-01-01T00:01:05Z");var scope=new Dictionary<string,object>(state);scope["target_pid"]=42;scope["method"]="xperf-profile-gameplay-range";fixture.Json("wpr-gameplay-cpu.json",scope);fixture.Write("wpr-gameplay-cpu.txt","other ( 43), 5000, 100.00, module\n");Reject(()=>DiagnosticQuality.WprGameplay(fixture.Root,state,42),"no target CPU samples");fixture.Write("wpr-gameplay-cpu.txt","inFAMOUS Second Son ( 42), 5000, 100.00, module\n");Check(I(DiagnosticQuality.WprGameplay(fixture.Root,state,42),"target_gameplay_profile_weight")==5000,"Target CPU samples lost.");state["window_finished"]="2026-01-01T00:01:06Z";Reject(()=>DiagnosticQuality.WprGameplay(fixture.Root,state,42),"stale");});
                Case("VTune gameplay PID/time filtering",delegate{var state=M("window_started","2026-01-01T00:00:05Z","window_finished","2026-01-01T00:01:05Z");var scope=new Dictionary<string,object>(state);scope["target_pid"]=42;scope["collection_start_utc"]="2026-01-01T00:00:00Z";scope["begin_seconds"]=6;scope["end_seconds"]=64;fixture.Json("vtune-gameplay-hotspots.json",scope);fixture.Write("vtune-gameplay-hotspots.csv","PID,Function,CPU Time,Module\n43,other,20,module\n");Reject(()=>DiagnosticQuality.VtuneCpu(fixture.Root,state,42),"no target CPU samples");fixture.Write("vtune-gameplay-hotspots.csv","PID,Function,CPU Time,Module\n42,work,1.5,module\n");Check(F(DiagnosticQuality.VtuneCpu(fixture.Root,state,42),"sampled_cpu_seconds")==1.5,"CPU time changed.");scope["begin_seconds"]=0;fixture.Json("vtune-gameplay-hotspots.json",scope);Reject(()=>DiagnosticQuality.VtuneCpu(fixture.Root,state,42),"time filter");scope["begin_seconds"]=6;scope["target_pid"]=41;fixture.Json("vtune-gameplay-hotspots.json",scope);Reject(()=>DiagnosticQuality.VtuneCpu(fixture.Root,state,42),"stale");});
