                Case("wall clock discontinuity",delegate{string path=Frames(fixture);fixture.Write("frames.csv",File.ReadAllText(path).Replace("1767225602000000000","1767225603000000000"));Check(I(DiagnosticQuality.Frames(fixture.Root,Epoch+.1,Epoch+1.9),"wall_clock_steps_over_5ms")==1,"Wall-clock step hidden.");});
                Case("large streaming TSV field",delegate{string path=fixture.Write("metrics.xls","event\tvalue\n"+new string('x',200000)+"\t1.5\n");var rows=DiagnosticData.Rows(path,'\t').ToArray();Check(rows.Length==2&&rows[1][0].Length==200000,"Large Nsight field was truncated.");});
