                Case("NVML snapshot clock",delegate{string path=Sensors(fixture);var lines=File.ReadAllLines(path);lines[0]=lines[0].Replace("field0","timestamp");for(int i=1;i<lines.Length;++i){var values=lines[i].Split(',');values[3]=new DateTime(2026,1,1,8,0,0).AddSeconds(i-1).ToString("yyyy/MM/dd HH:mm:ss.fff");if(i==lines.Length-1)values[0]="2026-01-01T00:02:00Z";lines[i]=String.Join(",",values);}fixture.Write("nvidia.csv",String.Join("\n",lines)+"\n");var row=DiagnosticQuality.Sensors(path,Epoch+5,Epoch+60,8*3600);Check(F(row,"last_unix_s")==Epoch+60&&F(row,"max_window_gap_seconds")==1,"Late observer time replaced snapshot time.");});
                Case("VTune calibration and bandwidth",delegate{Vtune(fixture);Check(F(DiagnosticQuality.Vtune(fixture.Root,Epoch+5,Epoch+65),"peak_gbps")==55,"Bandwidth changed.");fixture.Write("vtune-errors.log","Measuring peak DRAM bandwidth is not enabled");Reject(()=>DiagnosticQuality.Vtune(fixture.Root,Epoch+5,Epoch+65),"not calibrated");Vtune(fixture);string path=fixture.Paths.Child("vtune-summary.csv");fixture.Write("vtune-summary.csv",File.ReadAllText(path).Replace(",55,51,",",25,51,"));Reject(()=>DiagnosticQuality.Vtune(fixture.Root,Epoch+5,Epoch+65),"inconsistent");});
                Case("Nsight requested detailed frames",delegate{fixture.Write("user/captures/nsight/frame.ngfx-gputrace","raw fixture");fixture.Write("user/captures/nsight/BASE_UNLOCKED/D3DPERF_EVENTS.xls","event\ttime_ms\nDraw\t1.0\n");fixture.Write("user/captures/nsight/BASE_UNLOCKED/GPUTRACE_FRAME.xls","metric\t1.0\n");fixture.Write("diagnostics/nsight-output.log","");var state=M("nsight_sdk_accepted",true,"nsight_scene_anchor_utc","2026-01-01T00:00:00Z");Reject(()=>DiagnosticQuality.Nsight(fixture.Root,state,3),"fewer detailed frames");fixture.Write("user/captures/nsight/BASE_UNLOCKED/GPUTRACE_FRAME.xls","metric\t1.0\t2.0\t3.0\n");Check(I(DiagnosticQuality.Nsight(fixture.Root,state,3),"captured_frames")==3,"Detailed frame count changed.");state["nsight_sdk_accepted"]=false;Reject(()=>DiagnosticQuality.Nsight(fixture.Root,state,3),"start acknowledgement");});
                Case("PDB GUID/age identity",delegate{var launch=Symbols(fixture);Check((bool)DiagnosticQuality.Symbols(fixture.Paths,launch)["pdb_guid_age_match"],"Valid PDB/PE identity rejected.");string file=fixture.Paths.Child("Build/RelWithDebInfo/inFAMOUS Second Son.pdb");var bytes=File.ReadAllBytes(file);bytes[2060]^=1;File.WriteAllBytes(file,bytes);var receipt=Json.Read(fixture.Paths.Child("Build/RelWithDebInfo/build-receipt.json"));receipt["pdb_sha256"]=ProjectPaths.Hash(bytes);fixture.Json("Build/RelWithDebInfo/build-receipt.json",receipt);Reject(()=>DiagnosticQuality.Symbols(fixture.Paths,launch),"identity mismatch");});
                Case("complete report and failed artifact",delegate{Frames(fixture);var launch=Symbols(fixture);launch["pid"]=42;launch["prepared_at"]="2026-01-01T00:00:00Z";fixture.Json("launch.json",launch);var state=M("window_started","2026-01-01T00:00:00.1000000Z","window_finished","2026-01-01T00:00:01.9000000Z");fixture.Json("diagnostics/status.json",state);fixture.Json("diagnostics/plan.json",M("gpu_capture_backend","renderdoc","tools",new object[0]));fixture.Write("scripts/native/diagnostics/DiagnosticQuality.cs","synthetic validator fixture");fixture.Write("diagnostics/wpr-statistics.txt",WprText());var scope=new Dictionary<string,object>(state);scope["target_pid"]=42;scope["method"]="fixture";fixture.Json("diagnostics/wpr-gameplay-cpu.json",scope);fixture.Write("diagnostics/wpr-gameplay-cpu.txt","inFAMOUS Second Son ( 42), 5000, 100.00, module\n");Vtune(fixture,"diagnostics/");var report=DiagnosticQuality.Inspect(fixture.Paths,fixture.Root);Check((bool)report["complete"],"Complete fixture rejected: "+Json.Encode(report["errors"]));fixture.Write("diagnostics/wpr-statistics.txt",WprText().Replace("Lost Events : 0","Lost Events : 1"));report=DiagnosticQuality.Inspect(fixture.Paths,fixture.Root);Check(!(bool)report["complete"]&&!(bool)Json.Object(Json.Object(report["checks"])["wpr"])["validated"],"Failed WPR was masked by other artifacts.");});
            }
            if(Failures.Count>0)throw new InvalidOperationException(String.Join("\n",Failures));Console.WriteLine("Native data-quality regressions passed: "+passed+" cases, including complete and failed multi-artifact reports. No profiler or game was run.");
        }
